-error{margin:12px 20px;padding:10px;border:1px solid #fecaca;border-radius:6px;background:#fff7f7;color:#991b1b}.mr-library footer{font-size:12px;color:#94a3b8}@media(max-width:600px){.mr-library li{flex-direction:column;gap:10px}.mr-library-actions{justify-content:flex-end}.mr-library-search{flex-wrap:wrap}}
